// === Tab: mySketch ===
let bg;
ArrayList<Droplet> list = new ArrayList<Droplet>();
let G = .08; // gravity
let F = 0.95; // friction
let F_S = .1; // friction
let nsc = 1/70; // noise scale

function setup() {
  createCanvas(400, 600);
  ellipseMode(RADIUS);
  colorMode(HSB, 1);
  noStroke();
  bg = loadImage("https://openprocessing.org/sketch/1186284/files/background.png");
	background(0.05, 0.5, 0.3);
}

function draw() {
  image(bg, 0, 0);
  if (list.size() < 500) list.add(new Droplet());
  for (i = list.size()-1; i >= 0; i--) {
    let dr = list.get(i);
    if (dr.absorbed || dr.loc.y - dr.r > height) {
      list.remove(dr);
    }
  }
  for (let dr of list) {
    if (dr.absorbed) continue;
    dr.grow();
    dr.intersect();
    dr.fall();
    dr.draw();
  }
}

function col(x, y, br) {
  y = constrain(y, 0, height-1);
  let c = bg.pixels[y*width+x];
  let hue = 0.1;//hue(c); //let doesn't have the hue function??
  let sat = saturation(c);
  let bri = brightness(c)*br;
  return color(hue, sat, bri);
}

class Droplet {
  loc;
  r, v;
  absorbed;
  constructor() {
    loc = new PVector();
    loc.x = random(width);
    loc.y = random(height);
    r = 0.1;
    v = 0;
    absorbed = false;
  }
  function grow() {
    let area = r*r;
    let adds = area * .03;
    grow(adds);
  }
  function grow(adds) {
    r = pow(volume() + adds, 0.3333333);
  }
  function intersect() {
    for (let dr of list) {
      if (dr == this) continue;
      let dist = PVector.sub(this.loc, dr.loc).mag();
      dist -= (this.r + dr.r);
      if (dist < 0) {
        let vol0 = volume();
        let vol1 = dr.volume();
        let ratio = vol1 / (vol0 + vol1);
        loc.lerp(dr.loc, ratio);
        grow(vol1);
        dr.r = 0;
        dr.absorbed = true;
      }
    }
  }
  function fall() {
    v += volume() * G;
    let f_l = noise(loc.x*nsc, loc.y*nsc); // local friction
    v -= ((v+F_S+f_l*3) * F);
    v = constrain(v, 0, 5-4*f_l);
    loc.y += v;
  }
  function draw() {
    let x = loc.x / width;
    fill(col(floor(loc.x), floor(loc.y), 1.7));
    ellipse(loc.x, loc.y, r, r);
    fill(col(floor(loc.x), floor(loc.y), 0.8));
    ellipse(loc.x, loc.y-r*0.35, r*0.8, r*0.6);
  }
  area() { 
    return r*r;
  }
  volume() { 
    return r*r*r;
  }
}

